                l_cislo = vybraneRadky.cislo!;
                l_radek = vybraneRadky.radek!;
                l_ixs_pla = vybraneRadky.ixs_pla!;
                l_ixs_prr = vybraneRadky.ixs_prr!;
                // editable = editable && vybraneRadky.aktivita == Interface.AktivitaAkceEnum.Aktivni;
