                cnt.filter.cislo = l_cislo;
                cnt.filter.radek = l_radek;
                cnt.filter.ixs_pla = l_ixs_pla;
                cnt.filter.ixs_prr = l_ixs_prr;

                var radekISP: Gordic.Ada.Interface.GISPAkceDto; // = { };

